def is_good_triple(x, y, z):
    """
    Checks if (x, y, z) is a good triple, i.e., (x^z + 1) divides (x+1)^y.
    Handles large integers automatically in Python.
    """
    # Denominator D = x^z + 1
    try:
        D = pow(x, z) + 1
    except OverflowError:
        # This should not happen in standard Python integer arithmetic
        return False

    # Numerator N = (x+1)^y
    try:
        N = pow(x + 1, y)
    except OverflowError:
        return False

    if D == 0:
        # This case is impossible since x>=1, z>=1, so x^z >= 1, D >= 2.
        return False

    # Check divisibility: N % D == 0
    return N % D == 0

